{"file_path":"/app/decompress.py","content":"#!/usr/bin/env python3
"""Restore a resharded directory back to its original structure.

Usage
-----
    python /app/decompress.py <resharded_dir>

This reads every shard file produced by ``compress.py``, recreates the
original files and directories directly inside ``<resharded_dir>`` (in
place), and finally removes the shard files and now-empty shard
directories.
"""

from __future__ import annotations

import argparse
import os
import struct
import sys
from pathlib import Path

SHARD_MAGIC = b"C4SH"
SHARD_VERSION = 1
TYPE_FILE = 1
TYPE_DIR = 2


def iter_records(shard_path: Path):
    """Yield (kind, relative_posix_path, data_or_None) tuples from a shard."""
    with shard_path.open("rb") as fp:
        magic = fp.read(len(SHARD_MAGIC))
        if magic != SHARD_MAGIC:
            raise ValueError(f"{shard_path}: not a C4SH shard file (bad magic)")
        version = fp.read(1)
        if len(version) != 1:
            raise ValueError(f"{shard_path}: truncated shard header")

        while True:
            head = fp.read(1)
            if not head:
                break  # clean end of file
            kind = head[0]

            path_len_raw = fp.read(4)
            if len(path_len_raw) != 4:
                raise ValueError(f"{shard_path}: truncated record path length")
            path_len = struct.unpack(">I", path_len_raw)[0]
            path_raw = fp.read(path_len)
            if len(path_raw) != path_len:
                raise ValueError(f"{shard_path}: truncated record path")
            relpath = path_raw.decode("utf-8")

            if kind == TYPE_DIR:
                yield TYPE_DIR, relpath, None
                continue

            if kind == TYPE_FILE:
                size_raw = fp.read(8)
                if len(size_raw) != 8:
                    raise ValueError(f"{shard_path}: truncated record data length")
                size = struct.unpack(">Q", size_raw)[0]
                data = fp.read(size)
                if len(data) != size:
                    raise ValueError(f"{shard_path}: truncated record data")
                yield TYPE_FILE, relpath, data
                continue

            raise ValueError(f"{shard_path}: unknown record type {kind}")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Revert a directory resharded by compress.py back to its "
        "original structure and contents, in place."
    )
    parser.add_argument("resharded_dir", help="directory produced by compress.py")
    args = parser.parse_args(argv)

    root = Path(args.resharded_dir)
    if not root.is_dir():
        print(f"error: directory not found: {root}", file=sys.stderr)
        return 1

    shard_files: list[Path] = []
    directories: set[str] = set()
    files: dict[str, bytes] = {}

    for dirpath, _dirnames, filenames in os.walk(root):
        for filename in sorted(filenames):
            full = Path(dirpath) / filename
            try:
                with full.open("rb") as fp:
                    magic = fp.read(len(SHARD_MAGIC))
            except OSError as exc:
                print(f"warning: cannot read {full}: {exc}", file=sys.stderr)
                continue
            if magic != SHARD_MAGIC:
                print(
                    f"warning: skipping file without C4SH header: {full}",
                    file=sys.stderr,
                )
                continue

            shard_files.append(full)
            try:
                records = iter_records(full)
                for kind, relpath, data in records:
                    if kind == TYPE_DIR:
                        directories.add(relpath)
                    else:
                        if relpath in files:
                            print(
                                f"error: duplicate path in shards: {relpath}",
                                file=sys.stderr,
                            )
                            return 1
                        files[relpath] = data
            except ValueError as exc:
                print(f"error: {exc}", file=sys.stderr)
                return 1

    if not shard_files:
        print(f"error: no C4SH shard files found under {root}", file=sys.stderr)
        return 1

    # Recreate explicitly recorded directories, then the files.
    for rel in sorted(directories):
        (root / rel).mkdir(parents=True, exist_ok=True)
    for rel, data in sorted(files.items()):
        dest = root / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        with dest.open("wb") as fp:
            fp.write(data)

    # Remove the shard files themselves.
    for shard_path in shard_files:
        try:
            shard_path.unlink()
        except FileNotFoundError:
            pass

    # Prune the now-empty shard directories (bottom-up, never the root).
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        dirp = Path(dirpath)
        if dirp == root:
            continue
        try:
            dirp.rmdir()
        except OSError:
            pass  # still contains original data -> keep it

    print(
        f"Restored {len(files)} file(s) and {len(directories)} directory "
        f"record(s) in-place at {root}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
